def set_onboarding_start(apps, schema_editor):
    """Existing employees: the 15-day clock starts at their date of joining
    (so long-standing staff already need approval for HR edits); today
    when no joining date is set."""
    Employee = apps.get_model("website", "Employee")
    today = datetime.date.today()
    for emp in Employee.objects.all().only("id", "date_of_joining"):
        Employee.objects.filter(pk=emp.pk).update(onboarding_started_at=emp.date_of_joining or today)


def add_approval_feature(apps, schema_editor):
    """Grant "Approve Employee Changes" to the roles that may delete
    employees -- i.e. not HR (see 0040). Customisations made on the Roles &
    Permissions page are respected because it copies the current grants."""
    Group = apps.get_model("auth", "Group")
    Feature = apps.get_model("website", "Feature")
    RoleFeaturePermission = apps.get_model("website", "RoleFeaturePermission")

    feature, _ = Feature.objects.update_or_create(
        key=FEATURE["key"], defaults={k: v for k, v in FEATURE.items() if k != "key"},
    )
    approvers = set(
        RoleFeaturePermission.objects.filter(feature__key="employee_delete", can_edit=True)
        .values_list("role_id", flat=True)
    )
    for group in Group.objects.all():
        rfp, _ = RoleFeaturePermission.objects.get_or_create(role=group, feature=feature)
        rfp.can_approve = group.id in approvers and group.name != "HR"
        rfp.save()


def remove_approval_feature(apps, schema_editor):
    apps.get_model("website", "Feature").objects.filter(key=FEATURE["key"]).delete()


